#include <stdio.h>
int main(void) {
    for (int i = 1; i <= 4; i++) {
        for (int j = 1; j <= i; j++)
            printf("%d", j % 2);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    const char *s = "loop";
    int i = 0, v = 0, c = 0;
    do {
        switch (s[i]) {
            case 'a': case 'e': case 'i': case 'o': case 'u':
                v++; break;
            default: c++;
        }
    } while (s[++i] != '\0');
    printf("%d %d\n", v, c);
    return 0;
}

